const lessons=[{id:'math',subject:'МАТЕМАТИКА',title:'Как подружиться с числами',description:'Считаем до десяти и учимся складывать вместе с маленькой птичкой.',art:'2 + 3',pages:[['🐦 ⭐ ⭐','Знакомьтесь: птичка Сана','Сана нашла две звёздочки. Посчитайте их вслух: один, два!'],['⭐ ⭐ ＋ ⭐','Ещё одна звезда','Прилетела ещё одна звёздочка. Чтобы узнать, сколько их всего, сложим 2 и 1.'],['⭐ ⭐ ⭐','Вместе их три!','2 + 1 = 3. Сложение объединяет две группы. Покажите три пальчика.'],['🐦 ✦','Теперь ваша очередь','У Саны три звезды, и она нашла ещё две. Сколько стало? Посчитайте: 3 + 2 = 5.']]},{id:'read',subject:'ОБУЧЕНИЕ ГРАМОТЕ',title:'Буквы складываются в слова',description:'Знакомимся со звуками и собираем первое слово по слогам.',art:'А а',pages:[['🐦 А','У каждой буквы есть звук','Произнесите «а-а-а». Голос звучит свободно. Это гласный звук.'],['М + А','Буквы встречаются','Произнесите «м», а потом «а». Теперь соедините их: «ма». Это слог.'],['МА • МА','Собираем слово','Два слога «ма» образуют слово «мама». Прочитайте его вместе.'],['🐦 📖','Ищем знакомые буквы','Назовите слова, которые начинаются со звука «а». Например: арбуз.']]},{id:'world',subject:'ОКРУЖАЮЩИЙ МИР',title:'Четыре времени года',description:'Отправляемся в путешествие по природе и замечаем её изменения.',art:'☀ ❋',pages:[['🌱 🌷','Весна: природа просыпается','Становится теплее, тает снег и появляются первые цветы.'],['☀ 🌳','Лето: много света и тепла','Дни длинные. Деревья зелёные, созревают ягоды.'],['🍂 🍁','Осень: листья меняют цвет','Становится прохладнее. Листья желтеют и опадают.'],['❄ ☃','Зима: снежное время','На улице холодно. А какое время года сейчас? Назовите его признаки.']]}];
const grid=document.querySelector('#lesson-grid');function renderLessons(filter='all'){grid.innerHTML=lessons.filter(l=>filter==='all'||l.id===filter).map(l=>`<article class="lesson-card"><div class="card-art art-${l.id}"><span class="art-star">✦</span><span class="art-shape">${l.art}</span><span class="art-caption">ИСТОРИЯ ${String(lessons.indexOf(l)+1).padStart(2,'0')} / SANA</span></div><div class="card-body"><div class="card-kicker"><span>${l.subject}</span><span>4 шага</span></div><h3>${l.title}</h3><p>${l.description}</p><button class="card-open" data-lesson="${l.id}">Читать комикс <span>↗</span></button></div></article>`).join('')}renderLessons();document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelector('.filters .active').classList.remove('active');b.classList.add('active');renderLessons(b.dataset.filter)});
const modal=document.querySelector('#comic');let currentLesson,page=0;function drawPage(){let p=currentLesson.pages[page];document.querySelector('#comic-content').innerHTML=`<div class="comic-scene"><div class="scene-icons">${p[0]}</div><h3>${p[1]}</h3><p>${p[2]}</p></div>`;document.querySelector('#page-count').textContent=`${page+1} / ${currentLesson.pages.length}`;document.querySelector('#prev-page').disabled=page===0;document.querySelector('#next-page').textContent=page===3?'К игре ↗':'Далее →'}grid.onclick=e=>{let b=e.target.closest('[data-lesson]');if(!b)return;currentLesson=lessons.find(l=>l.id===b.dataset.lesson);page=0;document.querySelector('#comic-label').textContent=currentLesson.title;drawPage();modal.showModal()};document.querySelector('#close-comic').onclick=()=>modal.close();modal.onclick=e=>{if(e.target===modal){let r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}};document.querySelector('#prev-page').onclick=()=>{if(page>0){page--;drawPage()}};document.querySelector('#next-page').onclick=()=>{if(page<3){page++;drawPage()}else{modal.close();document.querySelector('#games').scrollIntoView({behavior:'smooth'})}};
const questions=[[2,1,[2,3,4]],[3,2,[4,6,5]],[4,2,[6,5,7]],[5,3,[7,8,9]],[6,4,[9,8,10]]];let q=0,solved=false;const answers=document.querySelector('#game-answers'),feedback=document.querySelector('#game-feedback'),next=document.querySelector('#game-next');function drawQuestion(){solved=false;next.hidden=true;document.querySelector('#game-count').textContent=`${q+1} / 5`;document.querySelector('#game-question').textContent=`Сколько будет ${questions[q][0]} + ${questions[q][1]}?`;document.querySelector('#game-stars').textContent='★ '.repeat(q)+'☆ '.repeat(5-q);feedback.textContent='Нажмите на правильный ответ';answers.innerHTML=questions[q][2].map(n=>`<button aria-label="Ответ ${n}">${n}</button>`).join('')}answers.onclick=e=>{if(e.target.tagName!=='BUTTON'||solved)return;const right=questions[q][0]+questions[q][1];if(Number(e.target.textContent)===right){solved=true;e.target.classList.add('correct');feedback.textContent='Верно! Ещё одна звезда в вашем созвездии.';document.querySelector('#game-stars').textContent='★ '.repeat(q+1)+'☆ '.repeat(4-q);next.hidden=false;next.textContent=q===4?'Сыграть ещё раз ↻':'Следующий вопрос →';if(q===4){document.querySelector('#game-question').textContent='Пять звёзд! Отличная работа!';feedback.textContent='Вы собрали всё созвездие и потренировали сложение.'}}else{e.target.classList.add('wrong');e.target.disabled=true;feedback.textContent=`Попробуйте ещё раз: начните с ${questions[q][0]} и добавьте ${questions[q][1]}.`}};next.onclick=()=>{q=q===4?0:q+1;drawQuestion()};drawQuestion();
